.mobile-status{display:none}
@media(max-width:620px){
  .shell{padding:calc(7px + env(safe-area-inset-top)) calc(7px + env(safe-area-inset-right)) calc(7px + env(safe-area-inset-bottom)) calc(7px + env(safe-area-inset-left))}
  .topbar{padding:0 3px}
  .brand{gap:8px}
  .server{gap:5px;font-size:8px;letter-spacing:-.03em}
  .worldhud{inset:10px 10px auto}
  .mobile-status{display:flex;position:absolute;top:57px;left:10px;right:10px;align-items:center;gap:8px;pointer-events:none}
  .mobile-vitals{flex:1;min-width:0;display:grid;gap:6px;padding:8px 10px;background:#16231dd9;border:1px solid #87948246;border-radius:9px;color:#d9dfcf;font:9px 'DM Mono',monospace}
  .mobile-stat>span{display:flex;justify-content:space-between;gap:6px;color:#abb8a7;white-space:nowrap}
  .mobile-stat b{color:#f3e8c9;font-weight:500}
  .mobile-meter{height:4px;margin-top:4px;background:#ffffff28;border-radius:8px;overflow:hidden}
  .mobile-meter i{display:block;width:100%;height:100%;background:#c96858;border-radius:8px;transition:width .25s}
  .mobile-meter.xp i{background:#d9b866}
  .mobile-commission{display:flex;flex-direction:column;align-items:center;gap:2px;min-width:75px;padding:8px 7px;background:#16231dd9;border:1px solid #87948246;border-radius:9px;color:#f0d99e;font:10px 'DM Mono',monospace}
  .mobile-commission span{font-size:7px;letter-spacing:.04em;color:#abb8a7}
  .mobile-commission b{font-size:9px;font-weight:500;color:#f3e8c9}
  .bottom-hud{bottom:calc(10px + env(safe-area-inset-bottom));left:10px;right:10px}
  .mobile-controls{bottom:calc(58px + env(safe-area-inset-bottom));left:10px}
  .mobile-controls .dpad{grid-template-columns:repeat(3,44px);gap:4px}
  .mobile-controls button{width:44px;height:44px;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
  .mobile-controls button:not(.blank){background:#17251fe8;box-shadow:0 3px 10px #0003}
  .skill{touch-action:manipulation;user-select:none;-webkit-tap-highlight-color:transparent}
  .toast{top:111px;max-width:calc(100% - 32px);white-space:normal;text-align:center}
}
@media(max-width:370px){
  .brand span{letter-spacing:.02em}
  .server{font-size:7px}
  .mobile-commission{min-width:67px}
  .hint{display:none}
  .bottom-hud{justify-content:flex-end}
}
@media(max-height:520px) and (orientation:landscape) and (max-width:900px){
  .shell{grid-template-rows:34px 1fr;padding-top:calc(4px + env(safe-area-inset-top));padding-bottom:calc(4px + env(safe-area-inset-bottom))}
  .topbar{min-height:0}
  .brand-mark{width:27px;height:27px}
  .brand span{margin-top:0}
  .mobile-status{top:48px;left:8px;right:auto;width:min(300px,48%)}
  .mobile-commission{display:none}
  .mobile-controls{bottom:calc(8px + env(safe-area-inset-bottom));left:8px}
  .mobile-controls .dpad{grid-template-columns:repeat(3,38px);gap:3px}
  .mobile-controls button{width:38px;height:38px}
  .bottom-hud{bottom:calc(8px + env(safe-area-inset-bottom));left:145px}
  .toast{top:12px}
}
</style>
