 function hit(){if(!playing)return;attack=.22;let m=mobs.filter(q=>q.alive&&Math.hypot(q.x-hero.x,q.y-hero.y)<28).sort((a,b)=>Math.hypot(a.x-hero.x,a.y-hero.y)-Math.hypot(b.x-hero.x,b.y-hero.y))[0];if(!m){say('Nothing in reach — get a little closer.');return}m.hp--;if(m.hp<=0){m.alive=false;kills++;hero.xp+=35;hero.coins+=3;log('A mossling scattered into <b>soft green sparks</b>. +35 XP, +3 ◈');if(kills===4){hero.xp+=90;hero.coins+=32;say('Commission complete! +90 XP · +32 ◈');log('<b>Commission complete!</b> The village board owes you one.')}else say('Mossling defeated · +35 XP');while(hero.xp>=hero.level*100){hero.xp-=hero.level*100;hero.level++;hero.hp=100;say('Level up! You reached level '+hero.level);log('<b>Level '+hero.level+'</b> — your journey continues.')}}else say('A clean hit!');update()}
 function skill(n){if(n==='1'){hit()}else if(n==='2'){if(items.potions>0&&hero.hp<100){items.potions--;hero.hp=Math.min(100,hero.hp+35);say('A restorative draught. +35 vitality');update()}else say(items.potions?'You are already at full vitality.':'No draughts left.')}}
 function move(dx,dy){if(!playing)return;hero.x=Math.max(-260,Math.min(260,hero.x+dx));hero.y=Math.max(-220,Math.min(220,hero.y+dy));hero.dir=dx||dy}

